size_t copy_prefix(char *dst, size_t capacity, const char *src) {
    size_t required = src ? strlen(src) : 0;
    if (dst && capacity > 0) {
        size_t copied = required < capacity - 1 ? required : capacity - 1;
        if (copied) memcpy(dst, src, copied);
        dst[copied] = '\0';
    }
    return required;
}

